input.command:
P=/private/tmp/claude-501/-Users-dm-dev-dev------harness/4c56fd8f-ccd6-4ef6-a546-d1f3c2d79696/scratchpad/lt/runs/init86/ws/plugins/dev-graph; FX=/private/tmp/claude-501/-Users-dm-dev-dev------harness/4c56fd8f-ccd6-4ef6-a546-d1f3c2d79696/scratchpad/lt/runs/init86/fx
cd $FX; find . -type d -not -path './.git*' | sort | tr '\n' ' '; echo
echo "--abs/token/node scan (non-template + templates):"
grep -rnE '/private/|/Users/|/tmp/|/home/|[A-Z]:\\\\' .dev-graph | grep -v '^.dev-graph/templates/' ; echo "abs-nontemplate rc=$?"
grep -rnE '/private/|/Users/|/tmp/|/home/' .dev-graph/templates | head; 
grep -rnE 'gh[pousr]_[A-Za-z0-9]{20,}|github_pat_|PVT_[A-Za-z0-9]|PVTSSF_|PVTF_|PVTI_|I_kw[A-Za-z0-9]|MDU6|"node_id"|"token"' .dev-graph | head; echo "token rc=$?"
python3 - <<EOF
import json,hashlib,os
P="$P";FX="$FX"
c=json.load(open(P+"/templates/template-contract.json"))
print("contract keys:",list(c.keys()))
def walk(o,acc):
    if isinstance(o,dict):
        for v in o.values(): walk(v,acc)
    elif isinstance(o,list):
        for v in o: walk(v,acc)
    elif isinstance(o,str) and ('.' in o) and not o.startswith('http') and len(o)<100: acc.add(o)
acc=set(); walk(c,acc)
print("strings w/ dot:",sorted(acc))
plug=sorted(os.listdir(P+"/templates")); loc=sorted(os.listdir(FX+"/.dev-graph/templates"))
print("plugin files",len(plug),"local",len(loc),"missing",set(plug)-set(loc),"extra",set(loc)-set(plug))
h=lambda p:hashlib.sha256(open(p,'rb').read()).hexdigest()
for f in plug:
    a,b=h(P+"/templates/"+f),h(FX+"/.dev-graph/templates/"+f)
    if a!=b: print("DIFF",f,"plugin",a,"local",b)
print("equal count",sum(h(P+"/templates/"+f)==h(FX+"/.dev-graph/templates/"+f) for f in plug))
EOF
tail -3 .dev-graph/templates/README.md; echo; diff $P/templates/README.md .dev-graph/templates/README.md; echo ---; cat docs/user-note.md; ls -la docs

